Definition VP_HTTP_ECAT_S48 : Z := 0x7ad70.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition hg_cells (b0 b1 : Z) (gj : list byte) : list cell := [C1 (Z_to_bv 8 b0); C1 (Z_to_bv 8 b1); CB 6 gj].

(* [comment removed for export] *)
Definition zeros36 : list byte := repeat (Z_to_bv 8 0) 36.
Definition hc_cells (g : bool) (j52 pad : list byte) : list cell :=
  if g then [C8 (Z_to_bv 64 VP_HTTP_ECAT); C8 (Z_to_bv 64 HTTP_CAT_ID); CB 36 zeros36; CB 4 pad]
  else [CB 52 j52; CB 4 pad].

