Definition gacq_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (G b0 b1 : Z) (gj : list byte) (m : word -> option byte) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(G, G + 2)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ ( (b0 = 0 /\ b1 = 0 /\ a0 = Z_to_bv 64 1 /\ rw_cells rsegs m' G (hg_cells 0 2 gj))
       \/ ((b0 = 1 \/ b1 = 1) /\ a0 = Z_to_bv 64 0 /\ rw_cells rsegs m' G (hg_cells b0 b1 gj))).
Scheme kc__1 := Elimination for Corelib.Init.Logic.or Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Logic.and Sort Prop.

Lemma gacq_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : word -> option byte) (G b0 b1 : Z) (gj : list byte),
  rw_cells rsegs m G (hg_cells b0 b1 gj) ->
  (b0 = 0 \/ b0 = 1) -> (b1 = 0 \/ b1 = 1) ->
  mem_inv rsegs m ->
  evt rsegs (gacq_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc G b0 b1 gj m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 G) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_CXA_GUARD_ACQUIRE) fc None m (seg_rom rsegs)).
