(* [comment removed for export] *)
Definition assign_tail_post (rav spv gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (D e lo : Z) (retD : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav spv gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned spv); (D, D + 24); (593200, 593200 + 64)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
