(* [comment removed for export] *)
Definition assign_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (D e lo : Z) (retD : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (assign_W D lo sp) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' D (ErrCodeCells (EC_http e))
    /\ HttpCat m' true /\ XStatics m'
    /\ (retD = true -> a0 = Z_to_bv 64 D).

Definition assign_stmt (pc_entry : Z) (retD : bool) : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (D e lo : Z) (g : bool) (junk : list byte),
  rw_cells rsegs m D [CB 24 junk] ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= D -> D + 24 <= 2^64 ->
  1 <= e < 2^31 ->
